#!/usr/bin/env python3
"""Reference model for seqtk size/comp/gap/listhet/hpc (v1.5-r133)."""
import sys

NT16 = {}
for ch, v in [('A',1),('C',2),('G',4),('T',8),
              ('M',3),('R',5),('W',9),('S',6),('Y',10),('K',12),
              ('V',7),('H',11),('D',13),('B',14)]:
    NT16[ch] = v
    NT16[ch.lower()] = v

def nt16(c):
    return NT16.get(c, 15)

def popcnt(x):
    return bin(x).count('1')

TS = {5, 10}          # R, Y  -> transition het
TV = {3, 6, 9, 12}    # M, S, W, K -> transversion het

def cpg_flags(seq):
    """cpg[i] = 1 if position i belongs to a CpG dinucleotide.
    A CpG is (C or Y) followed by (G or R), case-insensitive."""
    n = len(seq)
    f = [0]*n
    for i in range(n-1):
        a = nt16(seq[i]); b = nt16(seq[i+1])
        if a in (2, 10) and b in (4, 5):
            f[i] = 1; f[i+1] = 1
    return f

def comp_counts(seq, beg, end, upper_only=False, cpg=None):
    if cpg is None:
        cpg = cpg_flags(seq)
    cnt = [0]*7          # A C G T #2 #3 #4
    ncpg = ntv = nts = ncpgts = 0
    for i in range(beg, end):
        c = seq[i]
        if upper_only and c.islower():
            continue
        v = nt16(c)
        pc = popcnt(v)
        if pc == 1:
            cnt[{1:0, 2:1, 4:2, 8:3}[v]] += 1
        elif pc == 2:
            cnt[4] += 1
        elif pc == 3:
            cnt[5] += 1
        else:
            cnt[6] += 1
        is_ts = v in TS
        if pc == 2:
            if is_ts: nts += 1
            else:      ntv += 1
        if cpg[i]:
            ncpg += 1
            if is_ts: ncpgts += 1
    return cnt + [ncpg, ntv, nts, ncpgts]

def cmd_comp(records, upper_only=False, regs=None):
    out = []
    for name, seq, qual in records:
        cpg = cpg_flags(seq)
        if regs is None:
            c = comp_counts(seq, 0, len(seq), upper_only, cpg)
            out.append('\t'.join([name, str(len(seq))] + [str(x) for x in c]))
        else:
            for beg, end in regs.get(name, []):
                c = comp_counts(seq, max(beg,0), min(end, len(seq)), upper_only, cpg)
                out.append('\t'.join([name, str(beg), str(end)] + [str(x) for x in c]))
    return '\n'.join(out) + ('\n' if out else '')

def cmd_size(records):
    n = len(records)
    b = sum(len(s) for _, s, _ in records)
    return '%d\t%d\n' % (n, b)

def cmd_gap(records, min_size=50):
    out = []
    for name, seq, qual in records:
        i = 0; n = len(seq)
        while i < n:
            if popcnt(nt16(seq[i])) != 1:
                j = i
                while j < n and popcnt(nt16(seq[j])) != 1:
                    j += 1
                if j - i >= min_size:
                    out.append('%s\t%d\t%d' % (name, i, j))
                i = j
            else:
                i += 1
    return '\n'.join(out) + ('\n' if out else '')

def cmd_listhet(records):
    out = []
    for name, seq, qual in records:
        for i, c in enumerate(seq):
            if popcnt(nt16(c)) == 2:
                out.append('%s\t%d\t%s' % (name, i+1, c))
    return '\n'.join(out) + ('\n' if out else '')

def cmd_hpc(records):
    out = []
    for name, seq, qual in records:
        if len(seq) == 0:
            continue                       # zero-length records are dropped
        s = [seq[0]]
        for c in seq[1:]:
            if c != s[-1]:
                s.append(c)                # byte-exact, case sensitive
        out.append('>%s\n%s' % (name, ''.join(s)))
    return '\n'.join(out) + ('\n' if out else '')

# ---------------- kseq-like parser (per established shared facts) ----------------
def parse(data):
    recs = []
    i = 0; n = len(data)
    while True:
        while i < n and data[i] not in '>@':
            i += 1
        if i >= n:
            break
        i += 1
        j = i
        while j < n and not data[j].isspace():
            j += 1
        name = data[i:j]
        comment = ''
        if j < n and data[j] != '\n':
            k = data.find('\n', j)
            if k < 0: k = n
            comment = data[j+1:k]
            j = k
        i = j
        # sequence
        seq = []
        last_char = None
        while i < n:
            if i < n and data[i] == '\n':
                i += 1
            k = data.find('\n', i)
            if k < 0: k = n
            line = data[i:k]
            if line == '':
                if k >= n: i = n; break
                i = k
                continue
            if line[0] in '>@+':
                last_char = line[0]
                break
            if line.endswith('\r'): line = line[:-1]
            seq.append(line)
            i = k
            if k >= n: i = n; break
        seq = ''.join(seq)
        if last_char == '+':
            # skip the + line
            k = data.find('\n', i)
            if k < 0: k = n
            i = k
            qual = []
            ql = 0
            while i < n and ql < len(seq):
                if data[i] == '\n': i += 1
                k = data.find('\n', i)
                if k < 0: k = n
                line = data[i:k]
                if line.endswith('\r'): line = line[:-1]
                qual.append(line); ql += len(line)
                i = k
                if k >= n: i = n; break
            qual = ''.join(qual)
            if len(qual) != len(seq):
                break      # record discarded, parsing stops
            recs.append((name, seq, qual))
        else:
            recs.append((name, seq, ''))
    return recs

if __name__ == '__main__':
    cmd = sys.argv[1]
    args = sys.argv[2:]
    upper = False; regs = None; L = 50; fn = None
    it = iter(range(len(args)))
    i = 0
    while i < len(args):
        a = args[i]
        if a == '-u': upper = True
        elif a == '-l': L = int(args[i+1]); i += 1
        elif a == '-r':
            regs = {}
            for line in open(args[i+1]):
                f = line.split()
                if len(f) < 2: continue
                if not f[1].lstrip().isdigit(): continue
                beg = int(f[1])
                if len(f) >= 3 and f[2].isdigit():
                    end = int(f[2])
                else:
                    end = -1
                if end < 0:
                    if beg > 0: end = beg; beg = beg - 1
                regs.setdefault(f[0], []).append((beg, end))
            i += 1
        else: fn = a
        i += 1
    data = open(fn).read() if fn and fn != '-' else sys.stdin.read()
    recs = parse(data)
    if cmd == 'size':    sys.stdout.write(cmd_size(recs))
    elif cmd == 'comp':  sys.stdout.write(cmd_comp(recs, upper, regs))
    elif cmd == 'gap':   sys.stdout.write(cmd_gap(recs, L))
    elif cmd == 'listhet': sys.stdout.write(cmd_listhet(recs))
    elif cmd == 'hpc':   sys.stdout.write(cmd_hpc(recs))
